# BE-001 · Saved fields are persisted in the Customer table
# Requirement: R4 · Priority: P1 · Suites: sanity, regression
# Database
# Generated by the FlowPilot AI Test Factory (CogenSight)
import pytest


def test_update_persists(client, db):
    etag = client.get("/api/customers/1").headers["etag"]
    client.put("/api/customers/1", json={"City": "Boston"}, headers={"If-Match": etag})
    db.execute('SELECT "City" FROM PUB.Customer WHERE "CustNum" = 1')
    assert db.fetchone()[0] == "Boston"
